	string t=rnd_s(pl,n);
	vector<int> ct=rnd_v(n,q);
	ct.push_back(n);
	for (int i=1,pr=0; i<=q; i++){
		cout<<t.substr(pr,ct[i-1]-pr)<<endl;
		pr=ct[i-1];
	}
}

vector<int> rnd_v(int fw,int ti){ // 不可重复的划分 
	vector<int> ct;
	ct.push_back(0);
	for (int i=1,cr=0; i<ti; i++){
		ct.push_back(rnd_l(cr+1,fw-(ti-i)));
		cr=ct.back();
