C++ 选手请注意，由于答案可能超过 `long long` 的范围，请使用 `__int128` 存储答案，其用法如下：

`__int128` 的存储整数范围为 $-2^{127} \sim 2^{127}-1$，其运算等用法与 `int` 等整型数据类型的用法几乎一致，但无法用 `cin/cout` 进行输入输出，需要手写读写函数，具体模板如下：

```cpp
#include <bits/stdc++.h>

using namespace std;

__int128 x; // 定义一个 __int128 类型的数

// 读入 __int128 的函数，会返回读入的数。
__int128 read() {
    char c;
    bool isf = 0;
    while (!isdigit(c = getchar())) {
    	isf = (c == '-');
    }
    __int128 res = (c ^ 48);
    while (isdigit(c = getchar())) {
    	res = (res << 3) + (res << 1) + (c ^ 48);
    }
    return isf ? -res : res;
}

// 输出 __int128 的函数。需传入需要输出的数作为参数。
void write(__int128 x) {
    if (x < 0) {
    	putchar('-'), x = -x;
    } 
    if (x >= 10) {
    	write(x / 10);
    }
    putchar('0' + x % 10);
}

int main() {
	x = read(); // 读入
	write(x); // 输出
	return 0;
}
```

注：2024 年联合省选 T1 告诉了我们一个教训，在 `C++14` 的编译环境下，`__int128` 不可以用 `abs()` 取绝对值，否则会 CE。

