// wavelet
struct bits {
	vector<LL> bl;
	vector<int> c;
	void resize(int num) {
		bl.resize(((num+1)>>6)+1);
		c.resize(bl.size());
	}
	void set(int i,LL val) {bl[i>>6]|=(val<<(i&63));}
	void build() {
