struct wavelet {
	int h;
	vector<bits> B;
	vector<int> pos;
	void init(vector<int>& v) {
        h=__lg(*max_element(v.begin(),v.end()))+1;
		B.resize(h);pos.resize(h);
		for (int i=0;i<h;++i) {
			B[i].resize(v.size());
			for (int j=0;j<v.size();++j)
				B[i].set(j,(v[j]>>(h-i-1)&1));
			B[i].build();
			pos[i]=stable_partition(v.begin(),v.end(),[&](int c){
				return !(c>>(h-i-1)&1);
